{"file_path":"src/parse.js","content":"class ConfError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}

const newTable = () => ({ kind: 'table', map: new Map(), header: false })
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Line {
  constructor(text) {
    this.s = text
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  /** True at end of line or at a comment start (after whitespace). */
  atEnd() {
    this.ws()
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) throw new ConfError('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      const e = this.s[this.i + 1]
      if (e === undefined) throw new ConfError('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) {
        out += map[e]
        this.i += 2
      } else if (e === 'u') {
        const hex = this.s.slice(this.i + 2, this.i + 6)
        if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw new ConfError('invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        this.i += 6
      } else {
        throw new ConfError('invalid escape \\' + String.fromCodePoint(e.codePointAt(0)))
      }
    }
  }

  literalString() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) throw new ConfError('unterminated string')
    const out = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return out
  }

  name() {
    this.ws()
    const c = this.s[this.i]
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (this.i === st) throw new ConfError('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      this.ws()
      if (this.s[this.i] !== '.') return parts
      this.i++
      parts.push(this.name())
    }
  }

  value() {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
      throw new ConfError('expected a value')
    }
    if (c === '"') return { kind: 'string', value: this.basicString() }
    if (c === "'") return { kind: 'string', value: this.literalString() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (this.i < this.s.length && !' \t,]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { kind: 'boolean', value: true }
    if (w === 'false') return { kind: 'boolean', value: false }
    if (INT.test(w)) return { kind: 'integer', value: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { kind: 'float', value: Number(w.replace(/_/g, '')) }
    throw new ConfError('invalid value ' + w)
  }

  array() {
    this.i++
    const node = { kind: 'array', items: [], aot: false }
    for (;;) {
      if (this.atEnd()) throw new ConfError('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return node
      }
      node.items.push(this.value())
      if (this.atEnd()) throw new ConfError('unterminated array')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c !== ']') throw new ConfError('unterminated array')
    }
  }

  inline() {
    this.i++
    const table = newTable()
    if (this.atEnd()) throw new ConfError('unterminated inline table')
    if (this.s[this.i] === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) throw new ConfError('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') throw new ConfError('expected = in an inline table')
      this.i++
      const v = this.value()
      this.pendingAssign(table, keys, v)
      if (this.atEnd()) throw new ConfError('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') {
        this.i++
      } else if (c === '}') {
        this.i++
        return table
      } else throw new ConfError('unterminated inline table')
    }
  }
}

/** Walk into `table` along `keys` (all but the last), creating tables. */
function walk(table, keys, prefix, isHeader) {
  let cur = table
  const path = [...prefix]
  for (const k of keys) {
    path.push(k)
    let next = cur.map.get(k)
    if (!next) {
      next = newTable()
      cur.map.set(k, next)
    } else if (next.kind === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.kind !== 'table') {
      throw new ConfError(path.join('.') + ' is not a table')
    }
    cur = next
  }
  return { cur, path }
}

function assign(table, prefix, keys, value) {
  const { cur, path } = walk(table, keys.slice(0, -1), prefix)
  const last = keys[keys.length - 1]
  path.push(last)
  if (cur.map.has(last)) throw new ConfError('key ' + path.join('.') + ' is defined twice')
  cur.map.set(last, value)
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let currentPath = []
  let n = 0
  try {
    for (const text of lines) {
      n++
      const L = new Line(text)
      // Inline-table entries assign relative to a fresh table; paths are kept
      // from the root by tracking the prefix of the enclosing key.
      L.pendingAssign = (t, keys, v) => assign(t, L.prefix || [], keys, v)
      L.ws()
      const c = text[L.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') header(L, root, (t, p) => {
        current = t
        currentPath = p
      })
      else {
        const keys = L.dotted()
        L.ws()
        if (L.s[L.i] !== '=') throw new ConfError('expected key = value')
        L.i++
        L.prefix = [...currentPath, ...keys]
        const v = L.value()
        if (!L.atEnd()) throw new ConfError('trailing text after a value')
        assign(current, currentPath, keys, v)
      }
    }
  } catch (e) {
    if (e instanceof ConfError) {
      const err = new Error(e.reason)
      err.confMessage = `error: line ${n}: ${e.reason}`
      throw err
    }
    throw e
  }
  return root
}

function header(L, root, setCurrent) {
  L.i++
  const array = L.s[L.i] === '['
  if (array) L.i++
  const keys = L.dotted()
  L.ws()
  for (let k = array ? 2 : 1; k > 0; k--) {
    if (L.s[L.i] !== ']') throw new ConfError('unterminated table header')
    L.i++
  }
  if (!L.atEnd()) throw new ConfError('trailing text after a table header')
  const { cur, path } = walk(root, keys.slice(0, -1), [])
  const last = keys[keys.length - 1]
  path.push(last)
  const full = path.join('.')
  const existing = cur.map.get(last)
  if (array) {
    let arr = existing
    if (!arr) {
      arr = { kind: 'array', items: [], aot: true }
      cur.map.set(last, arr)
    } else if (arr.kind !== 'array' || !arr.aot) {
      throw new ConfError(full + ' is not an array of tables')
    }
    const t = newTable()
    t.header = true
    arr.items.push(t)
    setCurrent(t, path)
  } else {
    let t = existing
    if (!t) {
      t = newTable()
      cur.map.set(last, t)
    } else if (t.kind !== 'table') {
      throw new ConfError(full + ' is not a table')
    } else if (t.header) {
      throw new ConfError('table ' + full + ' is defined twice')
    }
    t.header = true
    setCurrent(t, path)
  }
}
"}

