  L.i++
  const array = L.s[L.i] === '['
  if (array) L.i++
  const keys = L.dotted()
  L.ws()
  for (let k = array ? 2 : 1; k > 0; k--) {
    if (L.s[L.i] !== ']') throw new ConfError('unterminated table header')
    L.i++
  }
  if (!L.atEnd()) throw new ConfError('trailing text after a table header')
  const { cur, path } = walk(root, keys.slice(0, -1), [])
  const last = keys[keys.length - 1]
  path.push(last)
  const full = path.join('.')
  const existing = cur.map.get(last)
  if (array) {
    let arr = existing
    if (!arr) {
      arr = { kind: 'array', items: [], aot: true }
      cur.map.set(last, arr)
    } else if (arr.kind !== 'array' || !arr.aot) {
      throw new ConfError(full + ' is not an array of tables')
    }
    const t = newTable()
    t.header = true
    arr.items.push(t)
    setCurrent(t, path)
