{"file_path":"src/render.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

function sortedKeys(node) {
  return [...node.map.keys()].sort(cmp)
}

function json(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (!keys.length) return '{}'
      return '{\n' + keys.map((k) => pad + JSON.stringify(k) + ': ' + json(node.map.get(k), indent + 1)).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((v) => pad + json(v, indent + 1)).join(',\n') + '\n' + end + ']'
    case 'integer':
      return node.value.toString()
    default:
      return JSON.stringify(node.value)
  }
}

export function renderJson(root) {
  return json(root, 0) + '\n'
}

export function renderKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.kind === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : path + '.' + k
        const child = node.map.get(k)
        lines.push(p + ' ' + child.kind)
        walk(child, p)
      }
    } else if (node.kind === 'array') {
      node.items.forEach((child, i) => {
        const p = path + '[' + i + ']'
        lines.push(p + ' ' + child.kind)
        walk(child, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
