/** Walk into `table` along `keys` (all but the last), creating tables. */
function walk(table, keys, prefix, isHeader) {
  let cur = table
  const path = [...prefix]
  for (const k of keys) {
    path.push(k)
    let next = cur.map.get(k)
    if (!next) {
      next = newTable()
      cur.map.set(k, next)
    } else if (next.kind === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.kind !== 'table') {
      throw new ConfError(path.join('.') + ' is not a table')
    }
    cur = next
  }
  return { cur, path }
}

function assign(table, prefix, keys, value) {
  const { cur, path } = walk(table, keys.slice(0, -1), prefix)
  const last = keys[keys.length - 1]
  path.push(last)
  if (cur.map.has(last)) throw new ConfError('key ' + path.join('.') + ' is defined twice')
  cur.map.set(last, value)
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let currentPath = []
  let n = 0
  try {
    for (const text of lines) {
      n++
      const L = new Line(text)
      // Inline-table entries assign relative to a fresh table; paths are kept
      // from the root by tracking the prefix of the enclosing key.
      L.pendingAssign = (t, keys, v) => assign(t, L.prefix || [], keys, v)
      L.ws()
      const c = text[L.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') header(L, root, (t, p) => {
        current = t
        currentPath = p
      })
      else {
        const keys = L.dotted()
        L.ws()
        if (L.s[L.i] !== '=') throw new ConfError('expected key = value')
        L.i++
        L.prefix = [...currentPath, ...keys]
        const v = L.value()
        if (!L.atEnd()) throw new ConfError('trailing text after a value')
        assign(current, currentPath, keys, v)
      }
    }
  } catch (e) {
    if (e instanceof ConfError) {
      const err = new Error(e.reason)
      err.confMessage = `error: line ${n}: ${e.reason}`
      throw err
    }
    throw e
  }
  return root
}

function header(L, root, setCurrent) {
  L.i++
  const array = L.s[L.i] === '['
  if (array) L.i++
  const keys = L.dotted()
  L.ws()
  for (let k = array ? 2 : 1; k > 0; k--) {
    if (L.s[L.i] !== ']') throw new ConfError('unterminated table header')
    L.i++
  }
  if (!L.atEnd()) throw new ConfError('trailing text after a table header')
  const { cur, path } = walk(root, keys.slice(0, -1), [])
  const last = keys[keys.length - 1]
  path.push(last)
  const full = path.join('.')
  const existing = cur.map.get(last)
  if (array) {
    let arr = existing
    if (!arr) {
      arr = { kind: 'array', items: [], aot: true }
      cur.map.set(last, arr)
    } else if (arr.kind !== 'array' || !arr.aot) {
      throw new ConfError(full + ' is not an array of tables')
    }
    const t = newTable()
    t.header = true
    arr.items.push(t)
    setCurrent(t, path)
  } else {
    let t = existing
    if (!t) {
      t = newTable()
      cur.map.set(last, t)
    } else if (t.kind !== 'table') {
      throw new ConfError(full + ' is not a table')
    } else if (t.header) {
      throw new ConfError('table ' + full + ' is defined twice')
    }
    t.header = true
    setCurrent(t, path)
  }
}
